        if isinstance(v, (int, float)):
            return float(v) * 2
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2)
                elif isinstance(item, str) and is_number(item):
                    new_list.append(float(item) * 2)
                else:
                    new_list.append(item)
            return new_list
        elif isinstance(v, str):
            if is_number(v):
                return float(v) * 2
            nums = re.findall(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', v)
            if nums:
                def replace_num(match):
                    num = float(match.group(0))
                    return str(num * 2)
                return re.sub(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', replace_num, v)
            return v
        else:
            return v

