from collections import Counter
# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}
    email_pattern = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
    def process(obj):
        if obj is None:
            return REPLACE_NONE
        if isinstance(obj, str):
            return email_pattern.sub(REPLACE_NONE, obj)
        if isinstance(obj, list):
            return [process(item) for item in obj if item is not None]
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items() if v is not None}
        return obj
    processed_data = process(data)
    flat_values = []
    def collect_values(obj):
        if isinstance(obj, dict):
