                collect_values(v)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item)
        else:
            flat_values.append(obj)
    collect_values(processed_data)
    value_counts = Counter(flat_values)
    return {"data": processed_data, "value_counts": value_counts}
